1: // DOCUMENTS: hop helpers shared by the two trace-state machines (trace.js
2: // and trace-stage6.js) — the queue drain, the backend pick, the serve
3: // record hand-off, and the final delivery call. Extracted by
4: // responsibility (guard-file-size): both machines run these identical hop
5: // semantics, so the one implementation lives here and each hop site passes
6: // its live trace in. Hop texts stay at the machines' own branch sites; the
7: // only frame minted here is the B-6b LB-hop pair, which the stage-2 branch
8: // shapes from the LB's live selection record (the branch's CHECKS comment
9: // in trace.js carries the claim for this pair).
10: 
11: // Serve from the front of the target's queue until the trace's own
12: // request (isYou) comes back, or the queue runs dry this tick.
13: export function drainUntilYou(targetServer, getTick) {
14:   for (;;) {
15:     const batch = targetServer.step(getTick());
16:     const you = batch.find((item) => item.isYou);
17:     if (you || batch.length === 0) return you;
18:   }
19: }
20: 
21: // The served-response hop's cache suffix: every real cache consult names
22: // its outcome, but the B-6d WRITE_DOWN record consulted nothing, so no
23: // "(cache …)" claim rides that frame — a raw "cache null" would narrate
24: // the record's absence as if null were a cache state.
25: export function serveCacheSuffix(trace) {
26:   return trace.dbOp === 'WRITE_DOWN' ? '' : ` (cache ${trace.cacheStatus})`;
27: }
28: 
29: export function backendFor(servers, targetAddress) {
30:   return servers.find((s) => s.address === targetAddress) ?? servers[0];
31: }
32: 
33: export function serveInto(trace, you, onServe) {
34:   trace.response = you.response;
35:   trace.status = you.status;
36:   trace.body = you.body;
37:   trace.routeId = you.routeId;
38:   onServe(you);
39: }
40: 
41: // Final hop: the rendered response lands on the browser the trace
42: // originated from (the engine routes it into the right browser state).
43: export function finishTo(trace, toAddress, onFinish) {
44:   onFinish({
45:     from: trace.from ?? '10.2',
46:     to: toAddress,
47:     request: trace.request,
48:     response: trace.response,
49:   });
50: }
51: 
52: // B-6b LB-hop frames, built from the LB's own selection state: an enqueued
53: // pick names the seat the cursor crossed (no skip keeps the byte shape),
54: // an all-down pool narrates the refusal record it received.
55: export function lbEnqueuedFrame(serverAddress, target, request, skippedAt) {
56:   return skippedAt
57:     ? `LB ${serverAddress} -> ${target} (${request}) queued — ${skippedAt} is down — skipped`
58:     : `LB ${serverAddress} -> ${target} (${request}) queued`;
59: }
60: 
61: export function lbRefusedFrame(serverAddress, record, request) {
62:   return `LB ${serverAddress} -> ${record.to} | ${request} => connection refused (nothing enqueued)`;
63: }
64: 
65: // CHECKS: B-6e — the stage-5 worker-tail frame (hop 8/8), minted from the
66: // live queue record: an async trace tails with the worker's commit, a
67: // synchronous trace finds the worker idle. While the worker is crashed the
68: // async tail reads the QUEUE's own state — the waiting count is the queue's
69: // live backlog — so a crashing trace stamps no phantom "finished job"
70: // commit and the 202 enqueue frames stay byte-identical; the synchronous
71: // tail keeps its byte shape (the crash does not touch the story that never
72: // consulted the worker). One implementation shared by trace.js and
73: // trace-stage6.js's chain.
74: export function workerTailFrame(trace, workerQueue, database) {
75:   const dbTarget = database ? database.primaryAddress : '10.30';
76:   const workerAddr = workerQueue ? workerQueue.workerAddress : '10.41';
77:   if (trace.asyncJob && workerQueue?.isCrashed?.() === true) {
78:     const waiting = workerQueue.pendingCount?.() ?? 0;
79:     return `Worker ${workerAddr} crashed — ${waiting} job(s) waiting in the queue (nothing committed)`;
80:   }
81:   return trace.asyncJob
82:     ? `Worker ${workerAddr} finished job and committed to Database ${dbTarget}`
83:     : `Worker ${workerAddr} idle — no async jobs in this trace`;
84: }
85: 
86: // The Stage 4+ database-hop frame, minted from the served record's own dbOp
87: // (the trace machine assigns trace.dbOp from it first): WRITE to the
88: // primary, the B-6d WRITE_DOWN refusal while the primary is down, a
89: // fresh/stale SELECT from the replica, or the warm-cache SKIP. One
90: // implementation shared by trace.js (stages 4 and 5) and trace-stage6.js's
91: // chain so the byte shape cannot drift between the machines.
92: export function dbHopFrame(trace, database, cache) {
93:   if (trace.dbOp === 'WRITE_DOWN') {
94:     return `Database WRITE FAILED (${trace.path}) @ ${database.primaryAddress} — primary down, nothing written`;
95:   }
96:   if (trace.dbOp === 'WRITE') {
97:     return `Database WRITE ${trace.path} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
98:   }
99:   if (trace.dbOp === 'SELECT') {
100:     return `Database SELECT ${trace.path} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
101:   }
102:   return `Database SKIP ${trace.path} (warm cache HIT @ ${cache.address})`;
103: }

