// Final hop count comes from the live trace shape: 3 for a refused
// trace (R1a — host-less the LB hop IS hop 3, so the walk ends right
// there; hosted the refusal lands on hop 4 and the next emission
// restarts through the same hop >= finalHop path — no phantom chain),
// 2 once the answer says NX, 6 for a CDN GET served from the edge
// ledger (HIT), 9 for a CDN MISS or non-GET pass-through, 9 for other
// hosted paths, 8 host-less.
const finalHop = trace.refused
  ? 3
  : trace.nx
    ? 2
    : trace.cdn
      ? trace.edgeStatus === 'HIT'
        ? 6
        : 9
      : trace.host
        ? 9
        : 8;

